// runOnceForAllItems: turn the Miniflux entries array into one item per entry,
// each carrying the system prompt + the user message for Ollama.
// The real reader profile is injected via the CURATOR_PROFILE env var (from the
// SOPS secret) so nothing personal lives in this workflow JSON. Falls back to a
// generic prompt if the env var is unset.
const res = $input.first().json;
const entries = Array.isArray(res.entries) ? res.entries : [];

const GENERIC = "You are a feed-triage assistant. Score each article 0-10 on how much it advances the reader's goals, then put it in one bucket.

READER (generic fallback - the real profile is injected from CURATOR_PROFILE)
Interested in: applied AI / LLM engineering, cloud and object storage, Kubernetes and inference infrastructure, and self-hosting. Favour hands-on engineering depth and things worth writing about; discount news, funding and product announcements.

SCORE 0-10 ON GOAL LEVERAGE, NOT GENERAL INTEREST
9-10  Deep how-it-works pieces the reader could reproduce, primary-source case studies, strong signal for the target field.
7-8   Strongly relevant engineering patterns, techniques on the learning path, or a clear angle the reader could write about.
5-6   Tangentially useful: general platform/SRE/cost content, a technique that could become a writeup, broad industry news with a concrete takeaway.
2-4   Low: generic tech news, announcements with no engineering substance.
0-1   Noise: unrelated, clickbait, marketing, duplicate-feeling.

BUCKETS (pick one): career | applied-ai | infra | storage | homelab | noise

OUTPUT
Return ONLY a JSON object, no prose, no code fence:
{"score": <int 0-10>, "bucket": "<one bucket>", "why": "<=25 words>", "publish_angle": "<a post title the reader could write, or empty string>"}";
const envP = ($env.CURATOR_PROFILE || '').trim();
const PROFILE = envP.length > 40 ? envP : GENERIC;

return entries.map((e) => {
  const html = e.content || e.summary || '';
  const text = String(html).replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, 1400);
  const feed = (e.feed && e.feed.title) || '';
  const category = (e.feed && e.feed.category && e.feed.category.title) || '';
  const userMsg = `TITLE: ${e.title}
FEED: ${feed}
MINIFLUX_CATEGORY: ${category}
AUTHOR: ${e.author || ''}
URL: ${e.url}
PUBLISHED: ${e.published_at || ''}

EXCERPT:
${text || '(no excerpt)'}`;
  return { json: { id: e.id, title: e.title, url: e.url, feed, category, sysPrompt: PROFILE, userMsg } };
});

// runOnceForEachItem: parse the model verdict, apply thresholds,
// quiet hours (22:00-07:30 America/Chicago) and a daily push cap.
const j = $json;
let v = {};
try { v = JSON.parse((j.message && j.message.content) || '{}'); }
catch (e) { v = { score: 0, bucket: 'noise', why: 'model returned non-JSON', publish_angle: '' }; }

let score = Math.round(Number(v.score));
if (!Number.isFinite(score)) score = 0;
score = Math.max(0, Math.min(10, score));
const bucket = String(v.bucket || 'noise');
const why = String(v.why || '').slice(0, 240);
const angle = String(v.publish_angle || '').slice(0, 240);

let action = 'skip';
if (score >= 8) action = 'notify';
else if (score >= 6) action = 'star';

const now = DateTime.now().setZone('America/Chicago');
const hm = now.hour + now.minute / 60;
const quiet = (hm >= 22 || hm < 7.5);

const sd = $getWorkflowStaticData('global');
const today = now.toFormat('yyyy-LL-dd');
if (sd.capDate !== today) { sd.capDate = today; sd.capCount = 0; }
const DAILY_CAP = 6;

if (action === 'notify') {
  if (quiet || (sd.capCount || 0) >= DAILY_CAP) action = 'star';
  else sd.capCount = (sd.capCount || 0) + 1;
}

const emoji = ({ 'career': '\uD83C\uDFAF', 'storage': '\uD83D\uDDC4\uFE0F', 'infra': '\u2699\uFE0F', 'applied-ai': '\uD83E\uDD16', 'homelab': '\uD83C\uDFE0', 'noise': '\u00B7' })[bucket] || '\u2022';
const gotifyPriority = score >= 9 ? 8 : 6;
const gotifyTitle = `${emoji} [${score}] ${j.feed || ''}`.slice(0, 120);
let gotifyMessage = `**${j.title}**\n\n${why}`;
if (angle) gotifyMessage += `\n\n\u270D\uFE0F Post angle: ${angle}`;
gotifyMessage += `\n\n${j.url}`;

return { json: { id: j.id, url: j.url, title: j.title, feed: j.feed, category: j.category, score, bucket, why, publish_angle: angle, action, gotifyPriority, gotifyTitle, gotifyMessage } };
